32	
33	constexpr size_t QUERY_INPUT_INDEX = 0;
34	constexpr size_t KEY_INPUT_INDEX = 1;
35	constexpr size_t VALUE_INPUT_INDEX = 2;
36	constexpr size_t SOFTMAXSUM_OUTPUT_INDEX = 1;
37	constexpr size_t ATTENTIONOUT_OUTPUT_INDEX = 3;
38	constexpr size_t INPUTLAYOUT_ATTRS_INDEX = 5;
39	constexpr size_t MIN_COPY_UINT_SIZE = 32;
40	constexpr size_t VALUE_100 = 100;
41	constexpr size_t VALUE_1024 = 1024;
42	constexpr uint32_t TILING_KEY_1 = 1U;
43	constexpr uint32_t FA_EMPTY_TILING_KEY = 1;
44	
45	struct EmptyArgs {
46	    uint32_t coreNum;
47	    uint32_t attentionOutFormerNum; // attentionOut的主核
48	    uint32_t attentionOutTailNum; // attentionOut的尾核
49	    uint32_t softmaxMaxFormerNum; // softmaxMax 和 softmaxSum的主核
50	    uint32_t softmaxMaxTailNum; // softmaxMax 和 softmaxSum的尾核
51	    uint64_t attentionOutSingleCoreDataSize; // attentionOut的每个主核处理的数据个数
52	    uint64_t attentionOutTailCoreDataSize; // attentionOut的每个尾核处理的数据个数
53	    uint64_t softmaxMaxSingleCoreDataSize;
54	    uint64_t softmaxMaxTailCoreDataSize;
55	    uint64_t attentionOutLastCoreDataSize = 0ULL; // 最后一个核应该处理的数据量
56	    uint64_t attentionOutLastCoreIndex = 0ULL; // 最后一个核起始地址
57	    uint64_t attentionOutBlockSize = 0ULL;
58	    uint64_t softmaxSumBlockSize = 0ULL;
59	    uint32_t aivActualNum = 0U;
60	    uint64_t tilingKey = 0ULL;
61	};
62	
63	static uint32_t Ceil(uint32_t num1, uint32_t num2)
64	{
65	    if (num2 == 0U) {
66	        return 0;
67	    }
68	    return (num1 + num2 - 1U) / num2;
69	}
70	
71	static ge::graphStatus CheckParams(const gert::TilingContext *context)
72	{
73	    if (context->GetAttrs() != nullptr && context->GetInputShape(QUERY_INPUT_INDEX) != nullptr &&
74	        context->GetInputShape(KEY_INPUT_INDEX) != nullptr && context->GetInputShape(VALUE_INPUT_INDEX) != nullptr) {
75	        auto &valueShape = context->GetInputShape(VALUE_INPUT_INDEX)->GetStorageShape();
76	        auto &keyShape = context->GetInputShape(KEY_INPUT_INDEX)->GetStorageShape();
77	        auto &queryShape = context->GetInputShape(QUERY_INPUT_INDEX)->GetStorageShape();
78	        const char *inputLayout = context->GetAttrs()->GetAttrPointer<char>(INPUTLAYOUT_ATTRS_INDEX);
79	        if (strlen(inputLayout) == 3) { // 3: BSH or SBH
80	            if (inputLayout[0] == 'B') {
81	                // layout is BSH
82	                OP_CHECK_IF((queryShape.GetDim(0) != keyShape.GetDim(0)),
83	                            OP_LOGE(context, "query or key shape is invalid"),
84	                            return ge::GRAPH_FAILED);
85	            } else {
86	                if (inputLayout[0] == 'T') { // TND  N1 != N2
87	                    // q_D != k_D
88	                    OP_CHECK_IF((queryShape.GetDim(2) != keyShape.GetDim(2)),
89	                                OP_LOGE(context, "query or key shape is invalid"),
90	                                return ge::GRAPH_FAILED);
91	                    return ge::SUCCESS;
92	                }
93	                // layout is SBH
94	                OP_CHECK_IF((queryShape.GetDim(1) != keyShape.GetDim(1)),
95	                            OP_LOGE(context, "query or key shape is invalid"),
96	                            return ge::GRAPH_FAILED);
97	            }
98	            // kD < vD
99	            OP_CHECK_IF((keyShape.GetDim(2) < valueShape.GetDim(2)),
100	                        OP_LOGE(context, "key or value shape is invalid"),
101	                        return ge::GRAPH_FAILED);
102	        } else if (strlen(inputLayout) == 4) { // 4: layout is BNSD or BSND
103	            OP_CHECK_IF((queryShape.GetDim(0) != keyShape.GetDim(0)),
104	                        OP_LOGE(context, "query or key shape is invalid"),
105	                        return ge::GRAPH_FAILED);
106	            OP_CHECK_IF((queryShape.GetDim(3) != keyShape.GetDim(3)),
107	                        OP_LOGE(context, "query or key shape is invalid"),
108	                        return ge::GRAPH_FAILED);
109	            OP_CHECK_IF((keyShape.GetDim(3) < valueShape.GetDim(3)),
110	                        OP_LOGE(context, "key or value shape is invalid"),
111	                        return ge::GRAPH_FAILED);
112	        } else {
113	            OP_LOGW(context, "invalid input_layout[%s].", inputLayout);
114	            return ge::GRAPH_FAILED;
115	        }
116	        return ge::SUCCESS;
117	    }
118	    OP_LOGW(context, "fail to get shape or attr from context");
119	    return ge::GRAPH_FAILED;
120	}
121	
122	static bool GetEmptyArgs(EmptyArgs &emptyArgs,
123	                         gert::TilingContext *context,
124	                         const uint32_t &coreNum,
125	                         const uint64_t &attentionOutShapeSize,
126	                         const int64_t &softmaxSumShapeSize)
127	{
128	    emptyArgs.coreNum = coreNum;
129	    OP_CHECK_IF((coreNum <= 0), OP_LOGE(context, "platform info is invalid, coreNum=%u.", coreNum), return false);
130	    auto kernelType = context->GetInputDesc(KEY_INPUT_INDEX)->GetDataType();
131	    OP_CHECK_IF((kernelType != ge::DT_FLOAT16 && kernelType != ge::DT_FLOAT && kernelType != ge::DT_BF16),
132	                OP_LOGE(context, "kernelType is invalid, kernelType is %d.", kernelType),
133	                return false);
134	    uint32_t kernelTypeSize = ge::GetSizeByDataType(kernelType);
135	    OP_CHECK_IF((kernelTypeSize <= 0),
136	                OP_LOGE(context, "kernelType size is invalid, kernelType size is %u.", kernelTypeSize),
137	                return false);
138	    // 计算 MIN_COPY_UINT_SIZE 块数
139	    emptyArgs.attentionOutBlockSize =
140	        Ceil(static_cast<uint32_t>(attentionOutShapeSize) * kernelTypeSize, MIN_COPY_UINT_SIZE);
141	    if (attentionOutShapeSize != 0ULL) {
142	        if (static_cast<uint64_t>(emptyArgs.attentionOutBlockSize % coreNum) == 0ULL) {
143	            emptyArgs.attentionOutTailCoreDataSize = 0ULL;
144	            emptyArgs.attentionOutFormerNum = coreNum;
145	            emptyArgs.attentionOutTailNum = 0U;
146	            emptyArgs.attentionOutSingleCoreDataSize =
147	                emptyArgs.attentionOutBlockSize / coreNum * MIN_COPY_UINT_SIZE / kernelTypeSize;
148	            emptyArgs.attentionOutLastCoreDataSize =
149	                emptyArgs.attentionOutSingleCoreDataSize -
150	                (emptyArgs.attentionOutBlockSize * MIN_COPY_UINT_SIZE / kernelTypeSize - attentionOutShapeSize);
151	            emptyArgs.attentionOutLastCoreIndex =
152	                static_cast<uint64_t>(emptyArgs.attentionOutFormerNum - 1U) * emptyArgs.attentionOutSingleCoreDataSize;
153	        } else {
154	            emptyArgs.attentionOutTailCoreDataSize =
155	                emptyArgs.attentionOutBlockSize / coreNum * MIN_COPY_UINT_SIZE / kernelTypeSize;
156	            emptyArgs.attentionOutSingleCoreDataSize =
157	                emptyArgs.attentionOutTailCoreDataSize + MIN_COPY_UINT_SIZE / kernelTypeSize;
158	            if (emptyArgs.attentionOutBlockSize > coreNum) {
159	                emptyArgs.attentionOutFormerNum = static_cast<uint32_t>(emptyArgs.attentionOutBlockSize % coreNum);
160	                emptyArgs.attentionOutTailNum = coreNum - emptyArgs.attentionOutFormerNum;
161	                emptyArgs.attentionOutLastCoreIndex =
162	                    static_cast<uint64_t>(emptyArgs.attentionOutFormerNum) * emptyArgs.attentionOutSingleCoreDataSize +
163	                    static_cast<uint64_t>(emptyArgs.attentionOutTailNum - 1U) * emptyArgs.attentionOutTailCoreDataSize;
164	                emptyArgs.attentionOutLastCoreDataSize =
165	                    emptyArgs.attentionOutTailCoreDataSize -
166	                    (emptyArgs.attentionOutSingleCoreDataSize * emptyArgs.attentionOutFormerNum +
167	                     emptyArgs.attentionOutTailCoreDataSize * emptyArgs.attentionOutTailNum - attentionOutShapeSize);
168	            } else {
169	                emptyArgs.attentionOutFormerNum = emptyArgs.attentionOutBlockSize;
170	                emptyArgs.attentionOutTailNum = 0U;
171	                emptyArgs.attentionOutLastCoreIndex = static_cast<uint64_t>(emptyArgs.attentionOutFormerNum - 1U) *
172	                                                      emptyArgs.attentionOutSingleCoreDataSize;
173	                emptyArgs.attentionOutLastCoreDataSize =
174	                    emptyArgs.attentionOutSingleCoreDataSize -
175	                    (emptyArgs.attentionOutFormerNum * emptyArgs.attentionOutSingleCoreDataSize -
176	                     attentionOutShapeSize);
177	            }
178	        }
179	    } else {
180	        emptyArgs.attentionOutFormerNum = 0U;
181	        emptyArgs.attentionOutTailNum = 0U;
182	        emptyArgs.attentionOutSingleCoreDataSize = 0ULL;
183	        emptyArgs.attentionOutTailCoreDataSize = 0ULL;
184	        emptyArgs.attentionOutLastCoreDataSize = 0ULL;
185	        emptyArgs.attentionOutLastCoreIndex = 0ULL;
186	    }
187	
188	    uint32_t floatDataSize = ge::GetSizeByDataType(ge::DT_FLOAT);
189	    OP_CHECK_IF(
190	        (floatDataSize <= 0), OP_LOGE(context, "float data size is invalid, size is %u.", floatDataSize), return false);
191	    // softmaxSum 和 softmaxMax 输出为 fp32
192	    emptyArgs.softmaxSumBlockSize =
193	        Ceil(static_cast<uint32_t>(softmaxSumShapeSize) * floatDataSize, MIN_COPY_UINT_SIZE);
194	    if (static_cast<uint64_t>(emptyArgs.softmaxSumBlockSize % coreNum) == 0ULL) {
195	        emptyArgs.softmaxMaxSingleCoreDataSize =
196	            emptyArgs.softmaxSumBlockSize / coreNum * MIN_COPY_UINT_SIZE / floatDataSize;
197	        emptyArgs.softmaxMaxTailCoreDataSize = 0U;
198	        emptyArgs.softmaxMaxFormerNum = coreNum;
199	        emptyArgs.softmaxMaxTailNum = 0U;
200	    } else {
201	        if (emptyArgs.softmaxSumBlockSize > coreNum) {
202	            emptyArgs.softmaxMaxFormerNum = static_cast<uint32_t>(emptyArgs.softmaxSumBlockSize % coreNum);
203	            emptyArgs.softmaxMaxTailNum = coreNum - emptyArgs.softmaxMaxFormerNum;
204	        } else {
205	            emptyArgs.softmaxMaxFormerNum = emptyArgs.softmaxSumBlockSize;
206	            emptyArgs.softmaxMaxTailNum = 0U;
207	        }
208	        emptyArgs.softmaxMaxTailCoreDataSize =
209	            emptyArgs.softmaxSumBlockSize / coreNum * MIN_COPY_UINT_SIZE / floatDataSize;
210	        emptyArgs.softmaxMaxSingleCoreDataSize =
211	            emptyArgs.softmaxMaxTailCoreDataSize + MIN_COPY_UINT_SIZE / floatDataSize;
212	    }
213	    emptyArgs.aivActualNum = std::max((emptyArgs.attentionOutFormerNum + emptyArgs.attentionOutTailNum),
214	                                      (emptyArgs.softmaxMaxFormerNum + emptyArgs.softmaxMaxTailNum));
215	    return true;
216	}
217	
218	static bool IsEmptyInput(gert::TilingContext *context)
219	{
220	    auto attentionOutShape = context->GetOutputShape(ATTENTIONOUT_OUTPUT_INDEX);
221	    OP_CHECK_NULL_WITH_CONTEXT(context, attentionOutShape);
222	
223	    auto queryShape = context->GetInputShape(QUERY_INPUT_INDEX);
224	    OP_CHECK_NULL_WITH_CONTEXT(context, queryShape);
225	
226	    auto keyShape = context->GetInputShape(KEY_INPUT_INDEX);
227	    OP_CHECK_NULL_WITH_CONTEXT(context, keyShape);
228	
229	    auto softmaxSumShape = context->GetOutputShape(SOFTMAXSUM_OUTPUT_INDEX);
230	    OP_CHECK_NULL_WITH_CONTEXT(context, softmaxSumShape);
231	
232	    int64_t attentionOutShapeSize = attentionOutShape->GetStorageShape().GetShapeSize();
233	    int64_t queryShapeSize = queryShape->GetStorageShape().GetShapeSize();
234	    int64_t keyShapeSize = keyShape->GetStorageShape().GetShapeSize();
235	    int64_t softmaxSumShapeSize = softmaxSumShape->GetStorageShape().GetShapeSize();
236	    if ((queryShapeSize == 0 || keyShapeSize == 0) && (attentionOutShapeSize != 0 || softmaxSumShapeSize != 0)) {
237	        /* 以 MIN_COPY_UINT_SIZE 为 32Byte说明, blocks为数据的块数, blocks与coreNum存在三种关系:
238	          (1) blocks % coreNum == 0
239	             主核数量为coreNum,主核处理块数为blocks / coreNum, 最后一个核处理非32Byte对齐的数据, 尾核数量为0
240	          (2) blocks % coreNum != 0
241	              (2.1) blocks < coreNum
242	                    主核数量为blocks,主核处理块数为1, 最后一个核处理非32Byte对齐的数据, 尾核数量为0
243	              (2.2) blocks > coreNum
244	                    主核数量为blocks % coreNum, 尾核数量为coreNum - (blocks % coreNum), 尾核处理块数为blocks / coreNum
245	                    主核处理块数为blocks / coreNum + 1,最后一个尾核处理非对齐场景
246	        (2.2)情况如下:
247	        |-------------主核块-----------------|------------尾核块-----------|非对齐块|
248	        |                                   |                             |       |
249	        |                                   |                             |       |
250	        |--------n*(blocks/coreNum+1)-------|-----m*(blocks/coreNum)------|<32Byte|
251	        */
252	        FlashAttentionScoreEnhanceTilingData *emptyInputTiling =
253	            context->GetTilingData<FlashAttentionScoreEnhanceTilingData>();
254	        emptyInputTiling->reset();
255	        auto compileInfoPtr =
256	            reinterpret_cast<const FlashAttentionScoreEnhanceCompileInfo *>(context->GetCompileInfo());
257	        OP_CHECK_IF(compileInfoPtr == nullptr, OP_LOGE(context, "compileInfoPtr is null"), return false);
258	        EmptyArgs emptyArgs;
259	        if (!GetEmptyArgs(emptyArgs, context, compileInfoPtr->aivNum, attentionOutShapeSize, softmaxSumShapeSize)) {
260	            return false;
261	        }
262	        emptyInputTiling->emptyInputTilingData.set_coreNum(emptyArgs.coreNum);
263	        emptyInputTiling->emptyInputTilingData.set_attentionOutFormerNum(emptyArgs.attentionOutFormerNum);
264	        emptyInputTiling->emptyInputTilingData.set_attentionOutTailNum(emptyArgs.attentionOutTailNum);
265	        emptyInputTiling->emptyInputTilingData.set_softmaxMaxFormerNum(emptyArgs.softmaxMaxFormerNum);
266	        emptyInputTiling->emptyInputTilingData.set_softmaxMaxTailNum(emptyArgs.softmaxMaxTailNum);
267	        emptyInputTiling->emptyInputTilingData.set_attentionOutSingleCoreDataSize(
268	            emptyArgs.attentionOutSingleCoreDataSize);
269	        emptyInputTiling->emptyInputTilingData.set_attentionOutTailCoreDataSize(emptyArgs.attentionOutTailCoreDataSize);
270	        emptyInputTiling->emptyInputTilingData.set_softmaxMaxSingleCoreDataSize(emptyArgs.softmaxMaxSingleCoreDataSize);
271	        emptyInputTiling->emptyInputTilingData.set_softmaxMaxTailCoreDataSize(emptyArgs.softmaxMaxTailCoreDataSize);
272	        emptyInputTiling->emptyInputTilingData.set_attentionOutLastCoreDataSize(emptyArgs.attentionOutLastCoreDataSize);
273	        emptyInputTiling->emptyInputTilingData.set_attentionOutLastCoreIndex(emptyArgs.attentionOutLastCoreIndex);
274	        context->SetTilingKey(FA_EMPTY_TILING_KEY);
275	        auto platformInfoPtr = context->GetPlatformInfo();
276	        OP_CHECK_IF(platformInfoPtr == nullptr, OP_LOGE(context, "platformInfoPtr is null"), return false);
277	        auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
278	        context->SetBlockDim(ascendcPlatform.CalcTschBlockDim(emptyArgs.aivActualNum, 0, compileInfoPtr->aivNum));
279	        size_t *workspaces = context->GetWorkspaceSizes(1);
280	        // workspace上预留100M
281	        workspaces[0] = VALUE_100 * VALUE_1024 * VALUE_1024;
282	        return true;
283	    }
284	    return false;
285	}
286	
287	ASCENDC_EXTERN_C ge::graphStatus TilingFlashAttentionScoreEnhance(gert::TilingContext *context)
288	{
289	    OP_LOGW(context, "Start registering tiling.");
290	    if (CheckParams(context) != ge::GRAPH_SUCCESS) {
291	        return ge::GRAPH_FAILED;
292	    }
293	
294	    auto platformInfoPtr = context->GetPlatformInfo();
295	    OP_CHECK_IF(platformInfoPtr == nullptr, OP_LOGE(context, "platformInfoPtr is null"), return ge::GRAPH_FAILED);
296	
297	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
298	
299	    OP_LOGW(context, "Current soc version is not ASCEND910_95.");
300	    if (IsEmptyInput(context)) {
301	        return ge::GRAPH_SUCCESS;
302	    }
303	
304	    auto resultCode = TilingRegistryNew::GetInstance().DoTilingImpl(context);
305	    return resultCode;
306	}
307	
308	ASCENDC_EXTERN_C ge::graphStatus TilingPrepareForFlashAttentionScoreEnhance(gert::TilingParseContext *context)
309	{
310	    auto platformInfoPtr = context->GetPlatformInfo();
311	    OP_CHECK_IF(platformInfoPtr == nullptr, OP_LOGE(context, "platformInfoPtr is null"), return ge::GRAPH_FAILED);
312	    auto compileInfoPtr = context->GetCompiledInfo<FlashAttentionScoreEnhanceCompileInfo>();
313	    OP_CHECK_IF(compileInfoPtr == nullptr, OP_LOGE(context, "compileInfoPtr is null"), return ge::GRAPH_FAILED);
314	
315	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
316	    compileInfoPtr->aivNum = ascendcPlatform.GetCoreNumAiv();
317	    compileInfoPtr->aicNum = ascendcPlatform.GetCoreNumAic();
318	    compileInfoPtr->socVersion = ascendcPlatform.GetSocVersion();
319	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, compileInfoPtr->ubSize);
320	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L1, compileInfoPtr->l1Size);
321	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_C, compileInfoPtr->l0cSize);
322	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L2, compileInfoPtr->l2CacheSize);
323	
324	    return ge::GRAPH_SUCCESS;
325	}
326	
327	IMPL_OP(FlashAttentionScoreEnhance)
328	    .Tiling(TilingFlashAttentionScoreEnhance)
329	    .TilingInputsDataDependency({7, 8, 9, 10, 11})
330	    .TilingParse<FlashAttentionScoreEnhanceCompileInfo>(
331	        TilingPrepareForFlashAttentionScoreEnhance); // 向框架注册入口函数
332	
333	} // namespace optiling
