47	    const gert::Shape *valueShape = context->GetInputShape(INDEX_2);
48	    OP_CHECK_NULL_WITH_CONTEXT(context, valueShape);
49	
50	    auto attrs = context->GetAttrs();
51	    OP_CHECK_NULL_WITH_CONTEXT(context, attrs);
52	    auto headNum = attrs->GetInt(INDEX_HEAD_NUM);
53	    OP_CHECK_NULL_WITH_CONTEXT(context, headNum);
54	    const char *inputLayout = attrs->GetAttrPointer<char>(INDEX_LAYOUT);
55	    OP_CHECK_NULL_WITH_CONTEXT(context, inputLayout);
56	
57	    std::string inputLayoutStr = std::string(inputLayout);
58	    for (auto &c : inputLayoutStr) {
