64	                "The inputLayout should be BSH/SBH/BSND/BNSD/TND(case-insensitive), but got %s.",
65	                inputLayoutStr.c_str());
66	        return GRAPH_FAILED;
67	    }
68	
69	    int64_t shapeB = 1;
70	    int64_t shapeS = 1;
71	    int64_t shapeT = 0;
72	    if (inputLayoutStr == "SBH") {
73	        shapeB = queryShape->GetDim(1);
74	        shapeS = queryShape->GetDim(0);
75	    } else if (inputLayoutStr == "TND") {
76	        shapeT = queryShape->GetDim(0);
77	    } else if (inputLayoutStr == "BSND" || inputLayoutStr == "BSH") {
78	        shapeB = queryShape->GetDim(0);
79	        shapeS = queryShape->GetDim(1);
80	    } else {
81	        // BNSD
82	        shapeB = queryShape->GetDim(0);
83	        shapeS = queryShape->GetDim(DIM_NUM_2);
84	    }
85	    OP_LOGI(context,
86	            "InferShape info: B=%ld, N=%ld, T=%ld, S=%ld, inputLayout=%s, dtype=%s",
87	            shapeB,
88	            *headNum,
89	            shapeT,
90	            shapeS,
91	            inputLayoutStr.c_str(),
92	            ge::TypeUtils::DataTypeToSerialString(queryDesc->GetDataType()).c_str());
93	
94	    // softmaxMax, fp32: (B, N, S, 8)
95	    gert::Shape *softmaxMaxShape = context->GetOutputShape(0);
96	    OP_CHECK_NULL_WITH_CONTEXT(context, softmaxMaxShape);
97	    // softmaxSum, shape same as softmaxMax
98	    gert::Shape *softmaxSumShape = context->GetOutputShape(1);
99	    OP_CHECK_NULL_WITH_CONTEXT(context, softmaxSumShape);
100	
101	    if (inputLayoutStr == "TND") {
102	        softmaxMaxShape->SetDimNum(DIM_NUM_3);
103	        softmaxMaxShape->SetDim(0, shapeT);
104	        softmaxMaxShape->SetDim(1, *headNum);
105	        softmaxMaxShape->SetDim(DIM_NUM_2, FLA_SOFTMAXMAX_F32_DIM0SHAPE);
106	    } else {
107	        // 0, 1, 2, 3, 4 : dim idx
108	        softmaxMaxShape->SetDimNum(DIM_NUM_4);
109	        softmaxMaxShape->SetDim(0, shapeB);
110	        softmaxMaxShape->SetDim(1, *headNum);
111	        softmaxMaxShape->SetDim(DIM_NUM_2, shapeS);
112	        softmaxMaxShape->SetDim(DIM_NUM_3, FLA_SOFTMAXMAX_F32_DIM0SHAPE);
