{
    auto &inputParams = tilingData->inputParams;
    OP_LOGD(context_, "[%s]try template[%s]", templateName, expectTemplate.ToString().c_str());
    if (!MatchTemplate()) {
        OP_LOGI(context_,
                "[%s]not match template[%s], input params: bn2gs1s2d[%ld, %ld, %ld, %ld, %ld, %ld], "
                "keepProb[%f]",
