    if (s2Size / s2BasicBlock == 8L && s2Size % s2BasicBlock > 0 && s2Size % s2BasicBlock <= 16L) {
        nRatio = 5L;
    }
    if (s2Size <= 2304 && s2Size >= 2049 && dSize == 64 &&
